/* ---------- Search input ---------- */
.six{min-height:320px;display:flex;justify-content:center;align-items:flex-start}
.six-box{width:100%;max-width:420px;background:var(--surface);border-radius:20px;box-shadow:var(--shadow);transition:box-shadow .35s var(--ease),transform .35s var(--ease)}
.six-box.f{box-shadow:var(--shadow-lift);transform:translateY(-1px)}
.six-in>svg{transition:color .25s}
.six-box.f .six-in>svg{color:var(--fg)}
.six-in{display:flex;align-items:center;gap:8px;height:46px;padding:0 10px 0 14px;color:var(--muted)}
.six-in input{flex:1;min-width:0;border:0;outline:0;background:transparent;font:inherit;font-size:14px;color:var(--fg)}
.six-in input::placeholder{color:var(--muted)}
.six-chips{display:flex;gap:4px}
.six-ch{display:inline-flex;align-items:center;gap:4px;height:24px;padding:0 4px 0 8px;border-radius:7px;background:var(--accent-bg);color:var(--accent);font-size:12px;font-weight:500;white-space:nowrap}
.six-ch button{display:grid;opacity:.6}.six-ch button:hover{opacity:1}
.six-x{width:26px;height:26px}
.six-res{padding:4px 6px 8px;border-top:1px solid var(--line)}
.six-g{font-size:11.5px;color:var(--muted);padding:8px 8px 4px}
.six-it{display:flex;align-items:center;gap:10px;width:100%;padding:7px 8px;border-radius:10px;font-size:13px;text-align:left;transition:background .15s}
.six-it:hover,.six-it.hl{background:var(--row)}
.six-it .ic{color:var(--muted);display:grid}
.six-it .d{margin-left:auto;font-size:12px;color:var(--muted)}
.six-it mark{background:transparent;color:var(--accent);font-weight:500}
.six-ans{margin:4px 2px 6px;padding:10px 12px;border-radius:12px;background:var(--accent-bg);font-size:12.5px;line-height:1.55;color:var(--fg2);display:flex;gap:8px}
.six-ans>svg{color:var(--accent);flex:none;margin-top:3px}
.six-ans .w{animation:sxw .4s var(--ease) both}
@keyframes sxw{from{opacity:0;filter:blur(3px)}}

DM.def('search-input', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{search}', I('search','xs')).replace('{x}', I('x','xs'));
  const box = $('.six-box', r), inp = $('.six-in input', r), dd = $('.six-dd', r), res = $('.six-res', r), chips = $('.six-chips', r), xB = $('.six-x', r), k = $('.six-k', r);
  const ITEMS = [['figma','Pricing v4','Figma'],['figma','Pricing mobile','Figma'],['file-text','Pricing research notes','Notion'],['code','PricingCard.tsx','GitHub'],['figma','Checkout flow','Figma'],['file-text','Brand voice guide','Notion'],['code','tokens.css','GitHub']];
  const SC = { figma:'Figma', notion:'Notion', github:'GitHub' };
  let scope = null, at;
  function paint(){
    const v = inp.value.trim(); xB.hidden = !v && !scope; k.hidden = !!v || !!scope;
    let h = '';
    if (/@\w*$/.test(v)){ const q = v.split('@').pop().toLowerCase(); h = '<div class="six-g">Filter by source</div>' + Object.entries(SC).filter(([key]) => key.startsWith(q)).map(([key, n]) => `<button class="six-it" data-sc="${n}"><span class="ic">${I(key === 'figma' ? 'figma' : key === 'github' ? 'code' : 'file-text','xs')}</span>${n}<span class="d">@${key}</span></button>`).join(''); }
    else if (!v && !scope){ h = '<div class="six-g">Recent</div>' + ['pricing contrast','checkout copy','tokens'].map(q => `<button class="six-it" data-q="${q}"><span class="ic">${I('history','xs')}</span>${q}</button>`).join(''); }
    else {
      const words = v.toLowerCase().split(/[^a-z0-9.]+/).filter(w => w.length > 2 && !['why','did','the','how','what','does'].includes(w)); const hit = i => !v || i[1].toLowerCase().includes(v.toLowerCase()) || words.some(w => i[1].toLowerCase().includes(w));
      const m = ITEMS.filter(i => (!scope || i[2] === scope) && hit(i)); const hw = words.find(w => m.some(i => i[1].toLowerCase().includes(w))) || v;
      if (v.split(' ').length > 2 || v.endsWith('?')) h += `<div class="six-ans">${I('spark','xs')}<span class="six-at"></span></div>`;
      h += m.length ? '<div class="six-g">' + m.length + (m.length === 1 ? ' result' : ' results') + '</div>' + m.map(i => `<button class="six-it"><span class="ic">${I(i[0],'xs')}</span><span>${hw ? i[1].replace(new RegExp(hw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i'), s => `<mark>${s}</mark>`) : i[1]}</span><span class="d">${i[2]}</span></button>`).join('') : '<div class="six-g">No matches. Press Enter to ask the agent</div>';
    }
    res.innerHTML = h; stagger($$('.six-it', res), 25);
    const a = $('.six-at', res);
    if (a){ clearInterval(at); const ws = 'Pricing changed on Sep 18: annual plans first, one CTA per card. Trial to paid is up 8.1 points since.'.split(' '); let i = 0; at = c.every(45, () => { if (i >= ws.length) return clearInterval(at); a.insertAdjacentHTML('beforeend', `<span class="w">${ws[i++]} </span>`); }); }
    $$('.six-it[data-q]', res).forEach(b => b.onmousedown = e => { e.preventDefault(); inp.value = b.dataset.q; paint(); });
    $$('.six-it[data-sc]', res).forEach(b => b.onmousedown = e => { e.preventDefault(); scope = b.dataset.sc; inp.value = inp.value.replace(/@\w*$/, ''); chips.innerHTML = `<span class="six-ch">${scope}<button aria-label="Remove filter">${I('x','xs')}</button></span>`; enter(chips.firstChild); $('button', chips).onmousedown = ev => { ev.preventDefault(); scope = null; chips.innerHTML = ''; paint(); }; paint(); });
  }
  inp.onfocus = () => { box.classList.add('f'); dd.classList.remove('shut'); paint(); };
  inp.onblur = () => { box.classList.remove('f'); dd.classList.add('shut'); };
  inp.oninput = paint;
  inp.onkeydown = e => { if (e.key === 'Backspace' && !inp.value && scope){ scope = null; chips.innerHTML = ''; paint(); } if (e.key === 'Escape') inp.blur(); };
  xB.onmousedown = e => { e.preventDefault(); inp.value = ''; scope = null; chips.innerHTML = ''; paint(); };
  c.on(document, 'pointerdown', e => { if (!r.contains(e.target) && document.activeElement !== inp){ box.classList.remove('f'); dd.classList.add('shut'); } });
  c.later(900, () => c.run(async () => { box.classList.add('f'); dd.classList.remove('shut'); paint(); await c.wait(600); for (const ch of 'why did pricing change?'){ inp.value += ch; paint(); await c.wait(45); } }));
});
